(39161, 'Psalms 119:100', 'Psalms', 119, 100, 'زه له مشرانو څخه زیات پوهېږم ځکه چې کړمه عمل ستا په اصولو باندې', 'زه له مشرانو چخه زیات پوهېزم جکه چې کرمه عمل ستا په اصولو باندې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_119_100.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39162, 'Psalms 119:101', 'Psalms', 119, 101, 'د بدو لارو مې ساتلي قدمونه خپل ځکه زه غواړم عمل وکړم ستا په کلام باندې', 'د بدو لارو مې ساتلی قدمونه خپل جکه زه غوارم عمل وکرم ستا په کلام باندې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_119_101.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39163, 'Psalms 119:102', 'Psalms', 119, 102, 'ستا قوانین مې له نظره غورځولي نه دي ځکه چې تا راته زده کړي هغه', 'ستا قوانین مې له نظره غورجولی نه دی جکه چې تا راته زده کری هغه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_119_102.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39164, 'Psalms 119:103', 'Psalms', 119, 103, 'دا ستا کلام دی څومره خوږ ماته حتی د شاتو نه هم زیات خوږ دی', 'دا ستا کلام دی چومره خوز ماته حتی د شاتو نه هم زیات خوز دی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_119_103.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
