(39167, 'Psalms 119:106', 'Psalms', 119, 106, 'ما خوړلی دی قسم او ورباندې ټینګ ولاړ یم چې عمل وکړمه زه ستا په عادلانه قوانینو', 'ما خورلی دی قسم او ورباندې تینګ ولار یم چې عمل وکرمه زه ستا په عادلانه قوانینو', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_119_106.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39168, 'Psalms 119:107', 'Psalms', 119, 107, 'زما دردونه او سختۍ دي ای څښتنه په رښتیا ډېر زیات لکه چې څنګه دې وعده کړې ده ما ژوندی وساته', 'زما دردونه او سختی دی ای چشتنه په رشتیا دېر زیات لکه چې چنګه دې وعده کرې ده ما ژوندی وساته', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_119_107.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39169, 'Psalms 119:108', 'Psalms', 119, 108, 'د شکرګزارۍ دعا قبوله کړه زما څښتنه ماته رازده کړه ته دې خپل قوانین', 'د شکرګزاری دعا قبوله کره زما چشتنه ماته رازده کره ته دې خپل قوانین', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_119_108.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39170, 'Psalms 119:109', 'Psalms', 119, 109, 'زه اچوم خپل ژوند خطر کې همېش خو نه هېروم به زه شریعت د ستا', 'زه اچوم خپل ژوند خطر کې همېش خو نه هېروم به زه شریعت د ستا', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_119_109.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39171, 'Psalms 119:110', 'Psalms', 119, 110, 'بدکاره خلکو راته دام ایښی دی خو سرکښي مې کړې نه ده ستا له قوانینو څخه', 'بدکاره خلکو راته دام ایشی دی خو سرکشی مې کرې نه ده ستا له قوانینو چخه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_119_110.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
