(39173, 'Psalms 119:112', 'Psalms', 119, 112, 'ما پرېکړه کړې ده چې به د مرګ تر ورځې ستا د قوانینو اطاعت کومه', 'ما پرېکره کرې ده چې به د مرګ تر ورجې ستا د قوانینو اطاعت کومه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_119_112.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
(39174, 'Psalms 119:113', 'Psalms', 119, 113, 'زه له دوه‌مخي سړي کرکه کوم خو ستا د شریعت سره زه مینه کوم', 'زه له دوه‌مخی سری کرکه کوم خو ستا د شریعت سره زه مینه کوم', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_119_113.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237840, 1761237840),
